<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useTrainingStore } from '@/stores/training'
import type { ExerciseDefinition } from '@/api/types'
import FilterSelect from '@/components/ui/FilterSelect.vue'
import { equipmentLabel, exerciseNameLabel, muscleLabel } from '@/utils/exerciseLabels'
import { useCoachWindow } from '@/composables/useCoachWindow'
const store=useTrainingStore(),query=ref(''),category=ref(''),equipment=ref(''),active=ref<ExerciseDefinition|null>(null)
const coach=useCoachWindow()
const categories=['胸','背','腿','肩','臂','核心']
const equipmentOptions=computed(()=>[...new Set(store.exercises.flatMap(item=>item.equipment))].sort())
const equipmentChoices=computed(()=>[{value:'',label:'全部器械'},...equipmentOptions.value.map(value=>({value,label:equipmentLabel(value)}))])
const filtered=computed(()=>store.exercises.filter(item=>(!category.value||item.category===category.value||item.target_muscles.includes(category.value))&&(!equipment.value||item.equipment.includes(equipment.value))&&(!query.value.trim()||`${item.name}${item.category}${item.target_muscles.join('')}`.toLowerCase().includes(query.value.trim().toLowerCase()))))
function clear(){query.value='';category.value='';equipment.value=''}
onMounted(async()=>{if(!store.exercises.length)await store.loadExercises();active.value||=store.exercises[0]??null})
</script>
<template><div class="library-workspace">
  <aside class="library-filters side-card"><div><h2>筛选动作</h2><p>选择后即时更新</p></div><label><span>关键词</span><input v-model="query" type="search" placeholder="动作名或肌群"></label><fieldset><legend>目标肌群</legend><button :class="{active:!category}" @click="category=''">全部</button><button v-for="item in categories" :key="item" :class="{active:category===item}" @click="category=item">{{item}}</button></fieldset><FilterSelect v-model="equipment" label="器械" :options="equipmentChoices" placeholder="全部器械"/><button class="text-button" @click="clear">清除筛选</button></aside>
  <section class="library-results"><header><div><h2>动作库</h2><p>点击动作查看要领</p></div><span>{{filtered.length}} 个动作</span></header><div v-if="store.loading" class="loading-skeleton"/><div v-else-if="filtered.length" class="exercise-card-grid"><button v-for="item in filtered" :key="item.id" class="exercise-card" :class="{active:active?.id===item.id}" @click="active=item"><div class="exercise-thumb"><img v-if="item.demo_images[0]" :src="item.demo_images[0]" :alt="`${exerciseNameLabel(item.name)}动作示意`" loading="lazy" referrerpolicy="no-referrer"><span v-else aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M6 12h12M4 9v6M20 9v6M8 8v8M16 8v8"/></svg></span></div><h3>{{exerciseNameLabel(item.name)}}</h3><p>{{item.target_muscles.map(muscleLabel).join('、')}}</p><div><span>{{muscleLabel(item.category)}}</span><span>{{item.equipment.length?item.equipment.map(equipmentLabel).join('、'):'无器械'}}</span></div></button></div><div v-else class="empty-state"><strong>没有找到匹配动作</strong><button class="button button-quiet" @click="clear">清除筛选</button></div></section>
  <aside class="exercise-detail-panel side-card"><template v-if="active"><header><span>{{muscleLabel(active.category)}}</span><h2>{{exerciseNameLabel(active.name)}}</h2><p>{{active.target_muscles.map(muscleLabel).join('、')}}</p><button class="button button-quiet exercise-ask-coach" type="button" @click="coach.openCoach(`请讲解${exerciseNameLabel(active.name)}的动作要领、呼吸和常见错误。`)">询问 AI 教练</button></header><video v-if="active.demo_video_url" :src="active.demo_video_url" :poster="active.demo_images[0]" controls playsinline preload="metadata"/><img v-else-if="active.demo_images[0]" :src="active.demo_images[0]" :alt="`${exerciseNameLabel(active.name)}动作示意`" referrerpolicy="no-referrer"><div v-else class="detail-media-empty">暂无示范媒体</div><section><h3>动作要领</h3><ul><li v-for="cue in active.cues" :key="cue">{{cue}}</li></ul></section><section><h3>常见错误与修正</h3><article v-for="item in active.common_errors" :key="item.error" class="error-correction"><b>{{item.error}}</b><span>{{item.correction}}</span></article></section><section class="variant-grid"><div><h3>退阶</h3><p>{{active.regressions.map(exerciseNameLabel).join('、')||'暂无'}}</p></div><div><h3>进阶</h3><p>{{active.progressions.map(exerciseNameLabel).join('、')||'暂无'}}</p></div></section><section><h3>替代动作</h3><p v-for="item in active.alternatives" :key="item.name"><b>{{exerciseNameLabel(item.name)}}</b>·{{item.scene}}</p></section><small>动作应在无痛且可控制的范围内完成。关节疼痛、锐痛或肿胀时停止该动作。</small></template><div v-else class="empty-state">选择一个动作查看详细要领</div></aside>
</div></template>
